"use strict";
(() => {
 const pages=[['index','↗','開始探索'],['00-start','00','一支箭頭，兩個數字'],['vectors','01','把箭頭接起來'],['basis','02','需要幾個方向？'],['matrices','03','讓整張方格動起來'],['composition','04','先做哪一步？'],['systems','05','兩條線，幾個答案？'],['rank','06','哪些方向消失了？'],['determinant','07','面積與倒帶'],['projection','08','把影子留在線上'],['least-squares','09','找最合適的一條線'],['eigen','10','不轉彎的方向'],['diagonalization','11','換一套座標看事情'],['qr','12','把方向整理整齊'],['svd','13','拆開一台矩陣機器'],['engineering','14','回到工程裡看看'],['glossary','Aa','名詞小字典'],['sources','↗','來源與模型邊界']];
 const current=document.body.dataset.page||'index';const active=pages.find(p=>p[0]===current)||pages[0];
 const header=document.getElementById('site-header');if(header)header.innerHTML='<a class="skip-link" href="#main-content">跳到主要內容</a><div class="header-inner"><a class="brand" href="index.html"><span class="brand-mark" aria-hidden="true">↗</span>線性代數小小實驗室</a><div class="header-links"><a class="wide-link" href="index.html#learning-path">學習地圖</a><a href="glossary.html">小字典</a><a class="wide-link" href="sources.html">參考資料</a><span class="header-note">看圖 · 動手 · 想明白</span></div></div>';
 const nav=document.getElementById('course-nav');if(nav){let html='<details class="course-menu"'+(window.matchMedia('(min-width:1100px)').matches?' open':'')+'><summary>學習路徑 · '+active[2]+'</summary>';pages.forEach((p,i)=>{if(i===0||i===9||i===16)html+=(i?'</ul>':'')+'<p class="nav-label">'+(i===0?'第一條路 · 箭頭與空間':i===9?'延伸探索 · 資料與分解':'隨時回來查')+'</p><ul class="course-links">';html+='<li><a href="'+p[0]+'.html"'+(p[0]===current?' aria-current="page"':'')+'><span class="nav-num">'+p[1]+'</span>'+p[2]+'</a></li>';});nav.innerHTML=html+'</ul><p class="nav-note">每張圖都可以慢慢玩。<br>從一支箭頭開始，也很好。</p></details>';}
 const footer=document.getElementById('site-footer');if(footer)footer.innerHTML='<div class="footer-inner"><p>線性代數小小實驗室 · 把抽象的數字，放回看得見的空間。</p><p><a href="sources.html">教材與模型說明</a>　·　<a href="index.html">回到起點</a></p></div>';
 const colors={blue:'#345ce8',coral:'#d96650',ink:'#182849',yellow:'#a5b116',green:'#3b8a74'};
 const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
 const fmt=(n,d=2)=>Number.isFinite(n)?Number((Math.abs(n)<1e-10?0:n).toFixed(d)).toLocaleString('zh-TW',{maximumFractionDigits:d}):'此處未定義';
 const line=(x1,y1,x2,y2,cls='axis')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" class="${cls}"/>`;
 const text=(x,y,label,cls='svg-label',anchor='start')=>`<text x="${x}" y="${y}" class="${cls}" text-anchor="${anchor}">${esc(label)}</text>`;
 const dot=(x,y,cls='marker',r=5)=>`<circle cx="${x}" cy="${y}" r="${r}" class="${cls}"/>`;
 const arrow=(x1,y1,x2,y2,color='blue',label='')=>{const col=colors[color]||color,dx=x2-x1,dy=y2-y1,L=Math.hypot(dx,dy);if(L<.01)return `<circle cx="${x1}" cy="${y1}" r="5" fill="${col}"/>`+(label?text(x1+10,y1-10,label):'');const ux=dx/L,uy=dy/L,h=Math.min(12,L*.45),w=Math.min(5,L*.2),bx=x2-h*ux,by=y2-h*uy;return `<line x1="${x1}" y1="${y1}" x2="${bx}" y2="${by}" stroke="${col}" stroke-width="3.5" stroke-linecap="round"/><polygon points="${x2},${y2} ${bx-w*uy},${by+w*ux} ${bx+w*uy},${by-w*ux}" fill="${col}"/>`+(label?text(x2+9,y2-10,label):'');};
 function plane(o={}){const{cx=410,cy=225,scale=42,extent=4,xlabel='x',ylabel='y'}=o;const ex=o.extentX??extent,ey=o.extentY??extent,X=v=>cx+v*scale,Y=v=>cy-v*scale;let axes='';for(let n=Math.ceil(-ex);n<=Math.floor(ex);n++){axes+=line(X(n),Y(-ey),X(n),Y(ey),'gridline');if(n)axes+=text(X(n),cy+21,n,'svg-small','middle');}for(let n=Math.ceil(-ey);n<=Math.floor(ey);n++){axes+=line(X(-ex),Y(n),X(ex),Y(n),'gridline');if(n)axes+=text(cx-10,Y(n)+5,n,'svg-small','end');}axes+=line(X(-ex),cy,X(ex),cy)+line(cx,Y(-ey),cx,Y(ey))+text(cx-10,cy+21,'0','svg-small','end')+text(X(ex)-1,cy-10,xlabel,'svg-label','end')+text(cx+10,Y(ey)+5,ylabel,'svg-label');return{X,Y,axes};}
 const mat=(A,v)=>[A[0][0]*v[0]+A[0][1]*v[1],A[1][0]*v[0]+A[1][1]*v[1]];
 const mul=(A,B)=>[[A[0][0]*B[0][0]+A[0][1]*B[1][0],A[0][0]*B[0][1]+A[0][1]*B[1][1]],[A[1][0]*B[0][0]+A[1][1]*B[1][0],A[1][0]*B[0][1]+A[1][1]*B[1][1]]];
 const vec=v=>'('+v.map(n=>fmt(n)).join(', ')+')';const matrix=A=>'['+A.map(r=>r.map(n=>fmt(n)).join('  ')).join('; ')+']';
 function bind(ids,update,defaults){ids.forEach(id=>{const el=document.getElementById(id);if(el){el.addEventListener('input',update);el.addEventListener('change',update);}});const reset=document.getElementById('reset');if(reset)reset.addEventListener('click',()=>{Object.entries(defaults||{}).forEach(([id,v])=>{const el=document.getElementById(id);if(el)el.value=v;});update();});update();}
 window.LA={fmt,line,text,dot,arrow,plane,mat,mul,vec,matrix,bind};
})();
